#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m;
    cin >> n >> m;

    // dp[i][j] 表示前 i 个位置，和模 n 余 j 的方案数
    vector<vector<long long>> dp(n + 1, vector<long long>(n, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int p = i; p <= m; p += i) {
                dp[i][j] = (dp[i][j] + dp[i - 1][(j - p % n + n) % n]) % MOD;
            }
        }
    }

    cout << dp[n][0] << endl;
    return 0;
}
